  const handleStartBatchSend = (selectedDevices: any[], targetPropKey: string, targetValue: any) => {
    setBatchSimPhase('running');
    setBatchProgress(0);
    setBatchLogs([`[INFO] [${new Date().toLocaleTimeString()}] 🚀 启动对 ${selectedDevices.length} 台设备批量下发任务...`]);
    setBatchResults([]);

    let step = 0;
    const totalSteps = selectedDevices.length;
    let currentLog = [`[INFO] [${new Date().toLocaleTimeString()}] 🚀 启动对 ${selectedDevices.length} 台设备批量下发任务...`];
    
    const interval = setInterval(() => {
      if (step < totalSteps) {
        const device = selectedDevices[step];
        const deviceAddrHex = device.addr.toString(16).padStart(2, '0').toUpperCase();
        const propLabel = getBatchPropsForTab(activeBatchTab).find(p => p.value === targetPropKey)?.label || '';
        
        currentLog.push(`[${new Date().toLocaleTimeString()}] [TCP] 正在连接设备: ${device.name} (Modbus ID: ${device.addr})...`);
        currentLog.push(`[${new Date().toLocaleTimeString()}] [TX] >> ${deviceAddrHex} 06 00 ${step.toString(16).padStart(2, '0').toUpperCase()} 00 01 C5 CE`);
        
        let valRep = typeof targetValue === 'boolean' ? (targetValue ? '00 01' : '00 00') : '00 FA';
        currentLog.push(`[${new Date().toLocaleTimeString()}] [RX] << ${deviceAddrHex} 06 00 ${step.toString(16).padStart(2, '0').toUpperCase()} ${valRep} D2 B8 (写入成功)`);
        currentLog.push(`[${new Date().toLocaleTimeString()}] [SUCCESS] 设备 [${device.name}] 已成功修改参数 [${propLabel}] -> ${typeof targetValue === 'boolean' ? (targetValue ? '开启/激活' : '关闭/休眠') : targetValue}`);
        
        setBatchLogs([...currentLog]);
        step++;
        setBatchProgress(Math.min(Math.round((step / totalSteps) * 100), 99));
      } else {
        clearInterval(interval);
        setBatchProgress(100);
        currentLog.push(`[${new Date().toLocaleTimeString()}] [SUCCESS] 批量下发作业全部执行完成！成功: ${totalSteps}台, 失败: 0台.`);
        setBatchLogs([...currentLog]);
        
        const results = selectedDevices.map(d => ({
          id: d.id,
          name: d.name,
          addr: d.addr,
          prop: getBatchPropsForTab(activeBatchTab).find(p => p.value === targetPropKey)?.label || '',
          value: typeof targetValue === 'boolean' ? (targetValue ? '开启/激活' : '关闭/休眠') : targetValue,
          status: 'success'
        }));
        setBatchResults(results);
        setBatchSimPhase('completed');
        
        setBatchDevices(prevDevices => 
          prevDevices.map(d => {
            const match = selectedDevices.find(sd => sd.id === d.id);
            if (match) {
              return {
                ...d,
                [targetPropKey]: targetValue
              };
            }
            return d;
          })
        );
      }
    }, 600);
  };

  const handleStartBatchRead = (selectedDevices: any[], targetPropKey: string) => {
    setBatchSimPhase('running');
    setBatchProgress(0);
    setBatchLogs([`[INFO] [${new Date().toLocaleTimeString()}] 🔎 启动批量属性读取轮询 (读取属性: ${getBatchPropsForTab(activeBatchTab).find(p => p.value === targetPropKey)?.label || ''})...`]);
    setBatchResults([]);

    let step = 0;
    const totalSteps = selectedDevices.length;
    let currentLog = [`[INFO] [${new Date().toLocaleTimeString()}] 🔎 启动批量属性读取轮询 (读取属性: ${getBatchPropsForTab(activeBatchTab).find(p => p.value === targetPropKey)?.label || ''})...`];
    
    const interval = setInterval(() => {
      if (step < totalSteps) {
        const device = selectedDevices[step];
        const deviceAddrHex = device.addr.toString(16).padStart(2, '0').toUpperCase();
        const propLabel = getBatchPropsForTab(activeBatchTab).find(p => p.value === targetPropKey)?.label || '';
        
        currentLog.push(`[${new Date().toLocaleTimeString()}] [POLL] 轮询设备 [${device.name}] (Modbus ID: ${device.addr}) 寄存器状态...`);
        currentLog.push(`[${new Date().toLocaleTimeString()}] [TX] >> ${deviceAddrHex} 03 00 ${step.toString(16).padStart(2, '0').toUpperCase()} 00 02 C5 CE`);
        
        const currentVal = device[targetPropKey];
        let displayVal = currentVal;
        if (typeof currentVal === 'boolean') {
          displayVal = currentVal ? '开启/激活' : '关闭/休眠';
        }
        
        currentLog.push(`[${new Date().toLocaleTimeString()}] [RX] << ${deviceAddrHex} 03 04 00 00 00 01 C5 CE (成功读取)`);
        currentLog.push(`[${new Date().toLocaleTimeString()}] [INFO] 设备 [${device.name}] 读取结果 [${propLabel}]: ${displayVal}`);
        
        setBatchLogs([...currentLog]);
        step++;
        setBatchProgress(Math.min(Math.round((step / totalSteps) * 100), 99));
      } else {
        clearInterval(interval);
        setBatchProgress(100);
        currentLog.push(`[${new Date().toLocaleTimeString()}] [SUCCESS] 批量属性读取全部轮询完成！成功率: 100% (${totalSteps}/${totalSteps})`);
        setBatchLogs([...currentLog]);
        
        const results = selectedDevices.map(d => {
          const currentVal = d[targetPropKey];
          let displayVal = currentVal;
          if (typeof currentVal === 'boolean') {
            displayVal = currentVal ? '开启/激活' : '关闭/休眠';
          }
          return {
            id: d.id,
            name: d.name,
            addr: d.addr,
            prop: getBatchPropsForTab(activeBatchTab).find(p => p.value === targetPropKey)?.label || '',
            value: displayVal,
            status: 'success'
          };
        });
        setBatchResults(results);
        setBatchSimPhase('completed');
      }
    }, 600);
  };
  
